export const getScreenUrl = () => {




  return `/api/screen`
}

/**
 * @summary Run combined speech + gait screening and fuse the scores
 */
export const screen = async (screenInput: ScreenInput, options?: Parameters<typeof customFetch>[1]): Promise<ScreenResult> => {
    const formData = new FormData();
if(screenInput.audio !== undefined) {
 formData.append(`audio`, screenInput.audio);
 }
if(screenInput.video !== undefined) {
 formData.append(`video`, screenInput.video);
 }
if(screenInput.language !== undefined) {
 formData.append(`language`, screenInput.language);
 }

  return customFetch<ScreenResult>(getScreenUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





